import{_ as o,o as t,c as a,ae as n}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"React Component and Hooks Props Naming","description":"","frontmatter":{"id":"2131725034","title":"React Component and Hooks Props Naming","state":"Approved","created":"2022-01-24T00:00:00.000Z","tags":["react"],"category":"JavaScript"},"headers":[],"relativePath":"adrs/2131725034/README.md","filePath":"adrs/2131725034/README.md"}'),r={name:"adrs/2131725034/README.md"};function i(s,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="react-component-and-hooks-props-naming" tabindex="-1">React Component and Hooks Props Naming <a class="header-anchor" href="#react-component-and-hooks-props-naming" aria-label="Permalink to &quot;React Component and Hooks Props Naming&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>When it comes to React, they are two categories of properties:</p><ul><li>Data (Information)</li><li>Callbacks (Events, Control Flow)</li></ul><p>Data properties are primarily used for displaying information or transforming into another set of data.</p><p>Callbacks are used to control the flow of data. Functions such as<code>onFilterAccount</code> and <code>onSortBy</code> would be used to filter and sort data. Callbacks can also react to events. The browser already makes a distinction between data and callback properties by prefixing the event handlers with <code>on</code>, for example: <code>onClick</code>, <code>onChange</code>, etc. The <code>on</code> prefix is used to indicate that the property is a callback and the component or hook controls the execution of the callback.</p><p>Understanding a React component API allows engineers to focus their attention on more important manners such as the business requirements.</p><p>When it comes to debugging problems in production and minified code where finding where the problem is a challenge and time critical. Being able to reduce the cognitive load reading through the code base is crucial.</p><p>Inconsistent property naming promotes bikeshedding, which slows down software development cycles in code review and results in unnecessary disagreements between developers.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>React Component and Hook <code>data</code> properties <strong>MUST</strong> be a noun.</li><li>React Component and Hook <code>callback</code> properties <strong>MUST</strong> a verb prefix with <code>on</code>.</li></ul>',11)])])}const u=o(r,[["render",i]]);export{m as __pageData,u as default};
